#include <zephyr/devicetree.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/printk.h>

/*
 * This file is assumed to be a test source, e.g.,
 * tests/drivers/fake_comp/src/main.c
 *
 * The original error 'DT_N_INST_0_zephyr_fake_comp_FULL_NAME' undeclared
 * suggests an incorrect usage of devicetree macros.
 *
 * DT_N_INST_0_zephyr_fake_comp is the node identifier for the first instance
 * of a device with compatible "zephyr,fake-comp".
 *
 * To access a property like "full-name" of this node, the correct macro is
 * DT_INST_0_ZEPHYR_FAKE_COMP_FULL_NAME.
 *
 * The original code likely tried to concatenate the node identifier macro
 * with the property name, which is not how Zephyr's devicetree macros work.
 */

void main(void)
{
    /* Check if the fake_comp_0 node is defined and enabled. */
    #if DT_NODE_HAS_STATUS(DT_N_INST_0_zephyr_fake_comp, okay)
        /* Use the correct macro to get the 'full-name' property. */
        const char *name = DT_INST_0_ZEPHYR_FAKE_COMP_FULL_NAME;
        printk("Fake component name: %s\n", name);
    #else
        printk("Fake component (instance 0) not found or not enabled in devicetree.\n");
    #endif
}
